import {createHash} from 'node:crypto';
const {compileArcMotion}=await import(process.argv[2]+'/scripts/v0/optimizer/arc_motion.ts');
const spec={duration:4,preroll:5,jitter:0,contacts:[.6,1.2,1.8,2.4,3,3.6].map(t=>({t,impact:.4})),axes:{air:()=>.5,speed:()=>.5}};
const options={budget:200000,samples:100,channel:12,radius:24,bidirectional:true,impactWeight:1,amplitudeWeight:1/3,arrivalMode:'speed',arrivalWeight:.3,headingWeight:.3,solver:'newton'};
const r=compileArcMotion(spec,17,options);
console.log(JSON.stringify({spec:{...spec,axes:{air:.5,speed:.5}},seed:17,options,trackHash:createHash('sha256').update(JSON.stringify(r.track)).digest('hex'),report:r.report,stats:r.stats,failure:r.failure}));
